### The Multi-Device Orchestration Sketch
Here is the complete Arduino sketch that arbitrates between the MAX7219 LED matrix and the RC522 RFID reader on a shared hardware SPI bus:

```cpp
#include <SPI.h>
#include <MFRC522.h>

// Dedicated Chip Select pins
const int CS_MATRIX = 10; // Pin 10: MAX7219 Display Select
const int CS_RFID   = 8;  // Pin 8:  RC522 RFID Select
const int RST_RFID  = 9;  // Pin 9:  RC522 Reset

MFRC522 rfid(CS_RFID, RST_RFID);

// Helper to write to MAX7219
void writeMatrix(byte reg, byte data) {
  digitalWrite(CS_RFID, HIGH);   // 1. Ensure RFID is asleep
  digitalWrite(CS_MATRIX, LOW);  // 2. Select MAX7219
  SPI.transfer(reg);
  SPI.transfer(data);
  digitalWrite(CS_MATRIX, HIGH); // 3. Deselect and latch
}

// Clear all 8 rows of matrix
void clearMatrix() {
  for (byte i = 1; i <= 8; i++) {
    writeMatrix(i, 0x00);
  }
}

void setup() {
  Serial.begin(9600);
  while (!Serial);

  // CRITICAL: Configure both CS pins as OUTPUT and HIGH before SPI.begin()!
  pinMode(CS_MATRIX, OUTPUT);
  pinMode(CS_RFID, OUTPUT);
  digitalWrite(CS_MATRIX, HIGH);
  digitalWrite(CS_RFID, HIGH);

  // Initialize hardware SPI bus
  SPI.begin();

  // Initialize MAX7219
  writeMatrix(0x0C, 0x01); // Normal operation
  writeMatrix(0x09, 0x00); // Raw matrix mode
  writeMatrix(0x0B, 0x07); // Scan all 8 rows
  writeMatrix(0x0A, 0x03); // Low-medium brightness
  clearMatrix();

  // Initialize RC522 RFID reader
  rfid.PCD_Init();
  Serial.println("Dual SPI Bus Operational: MAX7219 + RC522!");
}

void loop() {
  // 1. Check for RFID card presence
  if (rfid.PICC_IsNewCardPresent() && rfid.PICC_ReadCardSerial()) {
    Serial.println("Badge detected! Illuminating Matrix Eye...");

    // Draw an open eye on the matrix
    writeMatrix(4, B00111100);
    writeMatrix(5, B00111100);

    rfid.PICC_HaltA();
    delay(1000);
    clearMatrix();
  }
  delay(100);
}
```

### Code Breakdown:
- `pinMode(..., OUTPUT)` and `digitalWrite(..., HIGH)` for both CS pins before `SPI.begin()`: Guarantees that neither chip pulls lines during initialization.
- Both devices coexist on Pins 11 and 13 seamlessly because only one Chip Select pin is asserted LOW during any transfer!
